from pathlib import Path
from html.parser import HTMLParser
import hashlib,json,re

ROOT=Path(__file__).resolve().parents[1]
FILES=['index.html','library_ui.js','sequence_ui.js']
strings=set()
class Texts(HTMLParser):
 def handle_data(self,data):
  if re.search('[\u4e00-\u9fff]',data):strings.add(data)
 def handle_starttag(self,tag,attrs):
  for k,v in attrs:
   if v and re.search('[\u4e00-\u9fff]',v):strings.add(v)

main=(ROOT/'index.html').read_text(encoding='utf-8')
Texts().feed(main.split('<script>')[0])
for f in FILES:
 s=(ROOT/f).read_text(encoding='utf-8')
 s=s.split('<script>')[1].split('</script>')[0] if f.endswith('.html') else s
 for m in re.finditer(r'''('(?:\\.|[^'\\])*'|"(?:\\.|[^"\\])*")''',s):
  token=m.group()[1:-1]
  if re.search('[\u4e00-\u9fff]',token):strings.add(token)

