 p=ROOT/f; s=p.read_text(encoding='utf-8');before=hashlib.sha256(p.read_bytes()).hexdigest()
 for original in sorted(translation,key=len,reverse=True):
  s=s.replace(original,translation[original])
 s=s.replace('lang="zh-CN"','lang="en"').replace('"Segoe UI","Microsoft YaHei",sans-serif','Arial,"Segoe UI",sans-serif')
 for old,new in [('；','; '),('：',': '),('、',', '),('（',' ('),('）',')'),('。','.')]:s=s.replace(old,new)
 assert not re.search('[\u4e00-\u9fff]',s),f
 p.write_text(s,encoding='utf-8',newline='\n')
 receipts.append({'path':f,'before_sha256':before,'after_sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
